@forelse($reports as $report)
    @php($statusLabels = ['generated' => 'Generado', 'generating' => 'En proceso', 'failed' => 'Con error'])
    <article class="jira-report-row" data-report-id="{{ $report->unique_id }}"><div><strong>{{ $report->title }}</strong><small>{{ $report->from_date?->format('d/m/Y') }} a {{ $report->to_date?->format('d/m/Y') }} · {{ $report->project?->project_key ?: 'Todos los proyectos' }}</small></div><span class="jira-status-pill jira-status-{{ $report->status }}">{{ $statusLabels[$report->status] ?? $report->status }}</span><div class="jira-row-actions"><button class="btn btn-sm btn-outline-secondary" type="button" data-jira-report-view="{{ $report->unique_id }}" title="Ver reporte"><i class="fa-light fa-eye"></i></button>@if($report->status === 'generated')<a class="btn btn-sm btn-outline-secondary" href="{{ url('/admin/jira/reports/'.$report->unique_id.'/pdf') }}" title="Descargar PDF"><i class="fa-light fa-file-pdf"></i></a>@endif<button class="btn btn-sm btn-outline-secondary" type="button" data-jira-report-regenerate="{{ $report->unique_id }}" title="Regenerar"><i class="fa-light fa-arrows-rotate"></i></button><button class="btn btn-sm btn-outline-danger" type="button" data-jira-report-delete="{{ $report->unique_id }}" title="Eliminar"><i class="fa-light fa-trash-can"></i></button></div></article>
